 protected override void OnExiting(object sender,EventArgs args){if(!editor&&!quitting&&session!=null&&session.Error==null){var until=DateTime.UtcNow.AddSeconds(6);while(session.Busy&&DateTime.UtcNow<until)System.Threading.Thread.Sleep(10);if(session.Send(new(){Type="quit"}))while(session.Busy&&DateTime.UtcNow<until)System.Threading.Thread.Sleep(10);}base.OnExiting(sender,args);}
